INSERT INTO projects (slug, title, year, date, ref, category, location, medium, dimensions, edition, availability, series, featured, weight, image, gallery, body) VALUES ('the-grid', 'The Grid', 2024, '2024-10-12', 'G-2024-001', 'Architecture', 'Düsseldorf, Germany', 'archival pigment print', '180 × 220 cm', '3 of 7 + 2 AP', 'for-sale', 'Architecture', 1, 1, 'https://images.unsplash.com/photo-1480714378408-67cf0d13bc1b?w=2000&q=80&fit=crop&crop=entropy', '["https://images.unsplash.com/photo-1496564203457-11bb12075d90?w=1600&q=80&fit=crop&crop=entropy","https://images.unsplash.com/photo-1472289065668-ce650ac443d2?w=1600&q=80&fit=crop&crop=entropy"]', 'An exploration into the rigid geometry of urban planning. How the intersection of verticality and repetition creates a rhythm that demands objective distance from the viewer.

The series examines the skeletal truth of modern environments — vast logistical architectures whose scale only resolves when the human element is removed from the frame.');
INSERT INTO projects (slug, title, year, date, ref, category, location, medium, dimensions, edition, availability, series, featured, weight, image, gallery, body) VALUES ('the-distance', 'The Distance', 2023, '2023-09-28', 'G-2023-002', 'Landscape', 'Atacama, Chile', 'archival pigment print', '150 × 200 cm', 'Unique', 'sold', 'Landscapes', 1, 2, 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=2000&q=80&fit=crop&crop=entropy', '["https://images.unsplash.com/photo-1419242902214-272b3f66ee7a?w=1600&q=80&fit=crop&crop=entropy","https://images.unsplash.com/photo-1502082553048-f009c37129b9?w=1600&q=80&fit=crop&crop=entropy"]', 'Removing the human element from the frame to reveal the atmospheric neutrality of the landscape. A study on void space and the clarity that distance provides.

Captured at the solar fields of the Atacama — thousands of panels arranged in perfect concentric geometry, reflecting a pale and indifferent sky.');
INSERT INTO projects (slug, title, year, date, ref, category, location, medium, dimensions, edition, availability, series, featured, weight, image, gallery, body) VALUES ('rhein-ii', 'Rhein II', 1993, '1993-01-01', 'G-1993-018', 'Landscape', 'Germany', 'Chromogenic color print', '190 × 360 cm', '6 of 6 + 2 AP', 'sold', 'Landscapes', 0, 3, 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=2000&q=80&fit=crop&crop=entropy', '["https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?w=1600&q=80&fit=crop&crop=entropy","https://images.unsplash.com/photo-1433086966358-54859d0ed716?w=1600&q=80&fit=crop&crop=entropy"]', 'A strictly minimalist stratification of the river into horizontal bands. The composition removes incident and reduces the landscape to an almost abstract, objective register — water between flat green embankments beneath an overcast sky.');
INSERT INTO projects (slug, title, year, date, ref, category, location, medium, dimensions, edition, availability, series, featured, weight, image, gallery, body) VALUES ('board-of-trade', 'Board of Trade', 2007, '2007-01-01', 'G-2007-005', 'Architecture', 'Chicago, USA', 'C-print under plexiglass', '185 × 240 cm', '4 of 6 + 1 AP', 'for-sale', 'Stock Exchanges', 0, 4, 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=2000&q=80&fit=crop&crop=entropy', '["https://images.unsplash.com/photo-1472214103451-9374bd1c798e?w=1600&q=80&fit=crop&crop=entropy","https://images.unsplash.com/photo-1426604966848-d7adac402bff?w=1600&q=80&fit=crop&crop=entropy"]', 'Thousands of traders in coloured jackets captured in a structured swarm, composed from multiple viewpoints into a seamless, omniscient perspective where every detail holds focus. The trading floor becomes a pattern of colour and motion against dark architecture.');
INSERT INTO publications (slug, title, year, date, ref, category, publisher, author, isbn, pages, format, edition, image, gallery, body) VALUES ('catalogue-raisonne', 'Catalogue Raisonné', 2020, '2020-03-15', 'P-2020-001', 'Monograph', 'Steidl, Göttingen', 'George Geranios', '978-3-96999-123-4', '320 pages', 'Hardcover, 24 × 30 cm', 'First Edition', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=1500&q=80&fit=crop&crop=entropy', '["https://images.unsplash.com/photo-1454496522488-7a8e488e8606?w=1600&q=80&fit=crop&crop=entropy","https://images.unsplash.com/photo-1493863641943-9b68992a8d07?w=1600&q=80&fit=crop&crop=entropy"]', 'A comprehensive catalogue raisonné chronicling four decades of work. The volume documents all primary photographs produced between 1980 and 2020, arranged in systematic chronological order, with full provenance, exhibition history, and bibliographic references for each entry.

Essays by leading curators situate the practice within the broader history of large-format photography and the documentary tradition.');
INSERT INTO publications (slug, title, year, date, ref, category, publisher, author, isbn, pages, format, edition, image, gallery, body) VALUES ('landscapes', 'Landscapes', 2015, '2015-09-01', 'P-2015-002', 'Monograph', 'Hatje Cantz, Berlin', 'George Geranios', '978-3-7757-4000-0', '248 pages', 'Hardcover, 28 × 35 cm', 'First Edition', 'https://images.unsplash.com/photo-1418065460487-3e41a6c84dc5?w=1500&q=80&fit=crop&crop=entropy', '["https://images.unsplash.com/photo-1444723121867-7a241cacace9?w=1600&q=80&fit=crop&crop=entropy","https://images.unsplash.com/photo-1517677208171-0bc6725a3e60?w=1600&q=80&fit=crop&crop=entropy"]', 'A focused volume gathering the landscape work produced between 1989 and 2015 — from alpine passes and glacial valleys to the engineered landscapes of solar fields and industrial agriculture. The sequence traces a sustained study of distance, scale, and the geometry of the inhabited earth.');
INSERT INTO news (slug, title, date, summary, image, body) VALUES ('structural-integrity-and-the-grid', 'Structural Integrity and the Grid', '2023-10-12', 'An exploration into the rigid geometry of urban planning and the rhythm of repetition.', NULL, 'An exploration into the rigid geometry of urban planning. How the intersection of verticality and repetition creates a rhythm that demands objective distance from the viewer.

The grid is not merely a compositional device but an ideological one — a way of imposing legibility onto spaces that would otherwise resist it.');
INSERT INTO news (slug, title, date, summary, image, body) VALUES ('the-architecture-of-silence', 'The Architecture of Silence', '2023-09-28', 'Removing the human element to reveal the skeletal truth of our environments.', NULL, 'Removing the human element from the frame to reveal the skeletal truth of our environments. A study on void space and atmospheric neutrality.

The gallery void becomes its own subject: a space so emptied of incident that the architecture itself must carry the entire weight of meaning.');
